const architectures = [
{id:'MVC',name:'Model–View–Controller',tag:'Controller-led interaction',intro:'A campus controller interprets student actions, coordinates domain operations, and selects what the screen displays. This design uses a passive mobile View; MVC variants can also let Views observe Models.',nodes:['Course View','Campus Controller','Registration Model','Repository','University API'],back:'API response → repository → model → controller → refreshed course View',components:'Views display timetables, courses, results, notifications, and profiles. Feature controllers translate taps into operations. Models represent Student, Course, Enrollment, Result, and business rules. Repositories provide data access.',ui:'A Register tap calls CourseController.register(courseId). The controller invokes a registration use case in the Model and supplies a loading, success, or error presentation to the View.',api:'A remote data source behind the repository makes HTTP requests. Controllers call repository interfaces through domain operations; Views never call the API.',validation:'The View checks required input for immediate feedback. Model/domain rules check credit limits, prerequisites, and timetable clashes using available data. The server revalidates eligibility and capacity atomically.',state:'Keep screen-only state in a lifecycle-aware controller. Store enrollments and cached timetables in a repository, not only in a View. A shared session service owns authentication status.',trade:'Straightforward for small screens, but controllers can become large when navigation, retries, formatting, and business coordination accumulate. Domain services and repositories limit that growth.'},
{id:'MVP',name:'Model–View–Presenter',tag:'Explicit view contracts',intro:'Each campus screen exposes a small interface. Its Presenter controls presentation and can be tested with a fake View, without starting the mobile interface.',nodes:['Course View','Course Presenter','Register use case','Repository','University API'],back:'Enrollment response → repository → Presenter → view.showRegisteredCourses(courses)',components:'The passive View exposes methods such as showLoading and showCourses. A Presenter handles events and builds display values. Models and use cases contain campus data and rules. Repositories isolate storage and network access.',ui:'The View forwards onRegister(courseId) to the Presenter. The Presenter calls the use case, then explicitly invokes View methods for progress, errors, and confirmed registration.',api:'The Presenter depends on use cases/repository interfaces. A separate remote data source owns requests, timeouts, and response mapping; network code stays outside the View.',validation:'The View performs basic field checks; the Presenter maps validation failures to messages. Domain use cases enforce academic rules, and the server remains the final authority.',state:'The Presenter owns transient presentation state. Repositories retain durable enrollment data across navigation. Detach Views when destroyed and reattach/reload when returning to avoid stale references.',trade:'Presentation tests are simple and explicit. However, many View interfaces and forwarding methods add boilerplate, and lifecycle handling requires care to prevent leaks.'},
{id:'MVVM',name:'Model–View–ViewModel',tag:'Our recommendation',intro:'Campus screens observe state from feature ViewModels and send commands back. Repositories keep university data independent of screen lifecycles and connection quality.',nodes:['Course View','Course ViewModel','Register use case','Repository','University API'],back:'Server confirmation → local enrollment cache → observable ViewModel state → View re-renders',components:'Views render the interface. Feature ViewModels expose immutable UiState and commands. Models/use cases hold entities and academic rules. Repositories coordinate a local database and remote data sources. A session service manages credentials.',ui:'The View invokes RegisterCommand(courseId) and observes CoursesUiState. The ViewModel emits submitting, success, or failure states without holding a reference to a concrete screen.',api:'A repository delegates HTTP to an API client. ViewModels invoke use cases and observe repository data. A common authentication interceptor handles access tokens and controlled refresh.',validation:'The View checks input shape; the ViewModel exposes errors and command availability. Domain use cases apply credit, prerequisite, and clash rules. The server checks current records and seat availability before committing.',state:'ViewModels own loading, selection, and error state for their navigation scope. Repositories and local storage own timetable and enrollment data. Navigation recreates a ViewModel from repository state, rather than treating the screen as the database.',trade:'It separates redesigns from rules and supports observable cached data. Risks include oversized ViewModels, hidden binding errors, and complex asynchronous work; narrow use cases and explicit state models keep these manageable.'},
{id:'Redux / Flux',name:'Unidirectional state flow',tag:'Central, predictable state',intro:'Student actions become events that update a shared store. This proposal uses Redux: Flux is the broader family and may use several stores and a dispatcher.',nodes:['Course View','Register action','Async middleware','Repository / API','Success action'],back:'Success action → pure reducer → new store state → selector → Course View',components:'Views select data from the store. Actions describe events. Middleware runs asynchronous side effects. Pure reducers calculate new state. The Redux store holds feature slices for courses, timetable, profile, and session status.',ui:'A tap dispatches registrationRequested(courseId). Middleware runs the domain operation, then dispatches registrationSucceeded or registrationFailed. Reducers update state and subscribed Views render it.',api:'Middleware calls use cases/repositories that use an API client. Reducers must not perform requests, write storage, or read the clock: they compute state from previous state and an action.',validation:'Form checks stay close to the View. Domain use cases enforce academic checks before submitting, with final server enforcement. Reducers apply valid state transitions and store returned errors.',state:'A single store owns shared in-memory state; selectors derive display data. Durable caching/rehydration is a separate persistence policy. Store session status, not raw secrets; keep tokens in platform secure storage.',trade:'Action histories make navigation and state bugs easier to trace. The cost is extra action/reducer structure, persistence migrations, and careful separation of server data from temporary UI state.'},
{id:'BLoC',name:'Business Logic Component',tag:'Event → state streams',intro:'A feature BLoC accepts campus events and emits explicit states. The screen rebuilds from those states while repositories handle data and domain services handle academic policy.',nodes:['Course View','Register event','Courses BLoC','Repository','University API'],back:'Repository result → Courses BLoC emits Registered state → subscribed View rebuilds',components:'Views dispatch events and consume states. Feature BLoCs coordinate operations and presentation. Domain use cases hold reusable academic rules. Repositories connect local data sources and university services.',ui:'The View sends RegisterCourse(courseId). CoursesBloc handles the event, invokes a use case, and emits submitting, loaded, or error states. Navigation effects can use dedicated state listeners.',api:'BLoCs call repository/use-case interfaces; remote data sources perform HTTP. BLoCs should not embed endpoint details or duplicate storage logic.',validation:'The View checks simple input. A BLoC exposes validation messages returned by domain use cases. Authoritative registration, authorization, and availability checks run on the server.',state:'A scoped BLoC owns its current feature state. Repositories persist data beyond the BLoC lifetime. Define event ordering or deduplication for repeated taps and cancel subscriptions when a BLoC closes.',trade:'Explicit event/state transitions suit asynchronous workflows and testing. More event and state types increase code volume, and concurrent events need a deliberate policy.'}
];
const scenarios = [
['A','Timetable, even offline','Students must be able to view their timetable without an internet connection.','Change TimetableRepository to read from a per-student local database first and refresh it when connected. TimetableViewModel exposes cached entries, freshness, and an offline indicator.','Moderate and localized: the View already observes repository-backed state. The difficult work is defining freshness, migration, and account isolation rather than rewriting screens.','Introduce a local timetable data source, cache metadata (last successful sync), and a reconnect/background refresh coordinator.','The cache may be stale, and first-time users have no downloaded timetable. Show “No saved timetable” rather than an empty schedule, show the last sync time, clear account data on logout, and never promise background refresh will run on time.','Yes. MVVM remains appropriate; repository-based caching extends the original separation. Offline viewing is guaranteed only after a successful download.'],
['B','Registration under pressure','The registration system becomes extremely slow during registration week.','Improve the remote registration service and repository request policy. Keep ViewModel state responsive with progress, bounded timeouts, and an explicit pending outcome when the server result is unknown.','The client change is contained, but solving server contention is difficult and requires backend work. A presentation pattern cannot fix a slow university database.','Add server-side observability, database/query tuning, admission control, and scaling where measurements justify it. Use idempotency keys plus an operation-status endpoint; use a durable queue only if asynchronous registration is supported.','Blind retries can create duplicates or amplify load. Cache only suitable reads; never trust cached seat counts. Retry transient failures with bounded exponential backoff and jitter, honor rate limits, and reconcile unknown outcomes using the original key.','Yes for the mobile client. Extend the backend design independently. Show “Registered” only after authoritative confirmation, including when a queued request eventually completes.'],
['C','One student. Two devices.','Changes made on one device should eventually appear on the other.','Repositories must reconcile local data with versioned server records. A sync coordinator refreshes on foreground/reconnect and optionally on push invalidation. ViewModels observe the reconciled data.','Moderate to difficult. Existing repository boundaries help, but reliable synchronization requires an explicit conflict policy and server support.','Add record versions or ETags, a synchronization cursor, and an outbox only for permitted offline edits. Push notifications can signal a refresh; polling/foreground refresh provides a fallback.','Devices can overwrite each other, duplicate requests, or deliver changes out of order. For profile edits, reject stale versions and ask the student to resolve conflicts. Keep registration server-authoritative; deduplicate operations and retain unsent edits until acknowledged.','Yes. MVVM still fits; synchronization belongs in the data layer. Eventual consistency means temporary differences are expected, so expose pending/synced state and refresh after connectivity returns.'],
['D','A new look, the same rules','Introduce dark mode and completely redesign the user interface.','Change Views, navigation composition, theme tokens, and resources. Preserve domain use cases and repository contracts. Adapt ViewModel display properties only if the new interaction needs them.','Relatively easy because Views observe presentation state and academic rules are outside the interface. A structural redesign can still require new state mappings and accessibility work.','Add a theme resource system and a theme-preference service that follows the system setting or a saved user choice.','Contrast, hard-coded colors, lost focus, and unreadable charts can break the experience. Test both themes, large text, keyboard/screen-reader navigation, and shared ViewModel behavior after the redesign.','Yes. This is a strong reason to select MVVM. Keep color and layout decisions out of academic models and domain services.'],
['E','Courses that survive navigation','Registered courses disappear from the screen after returning from another page.','Inspect ViewModel lifetime, repository cache keys, navigation reconstruction, and state emissions. Persist confirmed enrollments in the repository; on return, observe/load them before refreshing.','Usually a localized fix once ownership is correct. MVVM makes the boundaries visible, but cannot prevent a wrongly scoped ViewModel or an accidental empty-state overwrite.','No new architectural pattern is required. Add a durable enrollment cache if absent and a regression test for register → leave → return, including offline return and process recreation.','Retaining all ViewModels forever can leak memory; caching without reconciliation can show dropped courses. Distinguish loading from truly empty, key data by student and term, and cancel old requests so late responses cannot replace newer state.','Yes. Repair lifecycle and state ownership. A screen disappearing does not prove records were deleted; compare server, repository, ViewModel, and rendered values to locate the fault.']
];
const names=['Atuba Chidubem Sean','Awofiranye Favor Opeyemi','Bantefa Gbolahan Nifemi','Divine Dominion Saviour','Edun Meyiwa-Meyigbene Nifemi','Egerega Joel Ndubuisi','Ejike Chiamaka Joan'];
const answer=(title,body,wide=false)=>`<section class="answer ${wide?'wide':''}"><h3>${title}</h3><p>${body}</p></section>`;
function overview(){return `<div class="wrap"><section class="hero"><div><div class="eyebrow">BU–SEN313 / Group assignment 01</div><h1>A connected campus.<br><em>By design.</em></h1><p class="lead">Five architectural approaches. One Student Campus App. A practical study of how good structure supports everyday student life.</p><div class="actions"><a class="primary" href="#architectures">Explore the architectures ↗</a><a class="text-link" href="#recommendation">Our recommendation →</a></div></div><div class="visual" aria-label="Recommended MVVM layers: student interface sends commands to ViewModel; ViewModel calls domain and repository; observable state returns to interface"><div class="visual-top"><span>THE CAMPUS BLUEPRINT</span><span>01 / MVVM</span></div><div class="stack"><div class="layer"><div><b>Student interface</b><small>Timetable · Courses · Results</small></div><span class="layer-number">01</span></div><div class="arrow">commands ↓ &nbsp; ↑ observable state</div><div class="layer blue"><div><b>ViewModel</b><small>Presentation state & student actions</small></div><span class="layer-number">02</span></div><div class="arrow">use cases ↓ &nbsp; ↑ data</div><div class="layer"><div><b>Domain & repository</b><small>Academic rules · Local cache · University API</small></div><span class="layer-number">03</span></div></div><div class="visual-caption">Separate responsibilities. Connect the experience.</div></div></section><div class="metrics"><div class="metric"><b>05</b><span>Architectures investigated</span></div><div class="metric"><b>07</b><span>Core app requirements</span></div><div class="metric"><b>05</b><span>Real-world change scenarios</span></div></div><section class="requirements"><div class="section-head"><div><div class="eyebrow">The brief</div><h2>Built around student life.</h2></div><p>A mobile application that keeps students informed, organised, and connected—even when the connection is unreliable.</p></div><div class="grid">${[['01','Course timetable','View scheduled classes, times, and locations.'],['02','Course registration','Select courses and submit valid registrations.'],['03','Examination results','View authorised, published academic results.'],['04','Notifications','Receive university and course updates.'],['05','Student profile','View and update permitted personal details.'],['06 + 07','Continuity & trust','Handle intermittent connectivity, authentication, and session expiry.']].map(x=>`<article class="card"><span class="index">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section class="dark-panel"><div><div class="eyebrow">The architectural decision</div><h2>MVVM, with a clear<br>data boundary.</h2><a class="primary" href="#recommendation">Read the rationale ↗</a></div><p>Separate the screen from its state, the academic rules from presentation, and the university API from local storage. This proposal makes offline reads, screen redesigns, and state recovery easier to reason about.</p></section></div>`}
function architecturePage(){return `<div class="wrap"><div class="page-heading"><div class="eyebrow">Part 01 / Architecture investigation</div><h1>Five patterns.<br>One campus experience.</h1><p class="lead">Compare the same registration journey across five simplified designs. Each approach covers responsibilities, communication, validation, and state.</p></div><div class="tabs" role="tablist" aria-label="Architecture">${architectures.map((a,i)=>`<button role="tab" id="tab-${i}" aria-controls="architecture-detail" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-architecture="${i}">${a.id}</button>`).join('')}</div><div id="architecture-detail" role="tabpanel" aria-labelledby="tab-0">${architectureDetail(0)}</div><section class="note"><p><strong>Shared assumption:</strong> the university provides authenticated APIs. These are proposed application designs, not a working university integration. All five patterns can use the same domain rules, repository, secure session service, and local cache.</p></section><a class="primary" href="#recommendation">Compare & choose an architecture →</a></div>`}
function architectureDetail(i){let a=architectures[i];return `<div class="detail-header"><h2>${a.name}</h2><span class="badge">${a.tag}</span></div><p>${a.intro}</p><figure class="diagram"><figcaption class="diagram-label">Data flow / student registers for a course</figcaption><div class="flow">${a.nodes.map(n=>`<div class="node">${n}</div>`).join('<span class="connector" aria-hidden="true">→</span>')}</div><p class="return-flow">${a.back}</p></figure><div class="answers">${answer('01 / Major components & responsibilities',a.components,true)}${answer('02 / UI communication & action flow',a.ui)}${answer('03 / Where API calls live',a.api)}${answer('04 / Where validation happens',a.validation)}${answer('05 / How state is managed',a.state)}${answer('06 / Practical tradeoff',a.trade,true)}</div>`}
function recommendation(){return `<div class="wrap"><div class="page-heading"><div class="eyebrow">Part 01 / Our recommendation</div><h1>Choose MVVM.<br><em>Design beyond the screen.</em></h1><p class="lead">MVVM with domain use cases and repositories is our preferred design for the Student Campus App. MVVM structures the presentation layer; caching, security, and synchronization require additional components.</p></div><div class="table-wrap"><table><thead><tr><th>Architecture</th><th>Strength in this app</th><th>Main cost</th></tr></thead><tbody><tr><td>MVC</td><td>Direct interaction flow for simple screens</td><td>Controller responsibility can grow quickly</td></tr><tr><td>MVP</td><td>Explicit, independently testable presentation</td><td>View contracts and lifecycle boilerplate</td></tr><tr class="selected"><td><strong>MVVM · Selected</strong></td><td>Observable data and replaceable Views</td><td>Binding and asynchronous state discipline</td></tr><tr><td>Redux / Flux</td><td>Traceable updates across shared features</td><td>Action structure and persistence policy</td></tr><tr><td>BLoC</td><td>Explicit events and asynchronous states</td><td>Extra types and event concurrency policy</td></tr></tbody></table></div><p>Our choice assumes a mobile framework with good observable-state support and a team comfortable with ViewModels. BLoC is a strong alternative for a Flutter team; Redux fits teams already using a centralized action-based state approach. No pattern automatically makes an app offline-capable or a server faster.</p><div class="answers">${answer('Fit for the student journey','TimetableViewModel observes cached classes; RegistrationViewModel exposes selected courses and submission status; ResultsViewModel displays authorised results; NotificationsViewModel manages the inbox; ProfileViewModel exposes editable fields. This gives each feature a clear presentation boundary.')}${answer('Reusable rules, replaceable screens','RegisterCourse and UpdateProfile use cases apply shared policy independently of layout. Views can be replaced for a redesign while domain tests and repository contracts remain useful.')}${answer('Offline reads and trustworthy writes','Repositories expose stored data immediately, then reconcile with the server. Timetable reads can work offline after a download. Course selections may be saved as drafts, but registration becomes confirmed only after the server accepts it.')}${answer('Authentication & session expiry','Store tokens in platform secure storage. A shared session service attempts one coordinated refresh when appropriate; failed refresh transitions to signed-out state and prompts login. Do not replay a potentially completed registration blindly. Clear user-specific caches on logout and scope all data by student.')}${answer('Notifications & intermittent connectivity','A push handler passes an event to the notifications repository, which refreshes the authorised inbox; notifications are hints, not authoritative records. On resume/reconnect, refresh missed updates. Use explicit cached, loading, empty, error, and confirmed states; retain useful data during a transient failure.')}${answer('Verification strategy','Test use cases with invalid prerequisites and credit limits; test ViewModels with fake repositories; test offline timetable loading, refresh failure, session expiry, duplicate registration attempts, and navigation away/back. Integration tests confirm server authorization and idempotency.')}</div><div class="dark-panel"><div><div class="eyebrow">Decision</div><h2>The pattern stays.<br>The data layer evolves.</h2></div><div><p>All five change scenarios can be addressed without replacing the presentation architecture. The hardest changes—server load and multi-device consistency—need more than a UI pattern.</p><a class="text-link" style="color:#78bcff" href="#scenarios">Explore the five scenarios →</a></div></div></div>`}
function scenarioPage(){return `<div class="wrap"><div class="page-heading"><div class="eyebrow">Part 02 / The “What if?”</div><h1>When requirements change,<br><em>what changes with them?</em></h1><p class="lead">Five stress tests for our proposed MVVM design. Each answer identifies the affected component, implementation difficulty, new components, risks, and continued suitability.</p></div>${scenarios.map((s,i)=>`<details class="scenario" ${i===0?'open':''}><summary><span class="letter">${s[0]}</span><div><h3>${s[1]}</h3><p>${s[2]}</p></div></summary><div class="scenario-body"><div class="answers">${answer('a / Component to change',s[3])}${answer('b / Easy or difficult?',s[4])}${answer('c / New components',s[5])}${answer('d / Problems the solution may create',s[6])}${answer('Does the original architecture still fit?',s[7],true)}</div></div></details>`).join('')}<div class="note"><p><strong>Overall conclusion:</strong> retain MVVM, domain use cases, and repositories. Add infrastructure deliberately. Separation makes changes easier to localize; reliable offline behavior, performance, and consistency still depend on sound data and backend design.</p></div></div>`}
function about(){return `<div class="wrap"><div class="page-heading"><div class="eyebrow">About / The project team</div><h1>Seven creators.<br><em>One shared blueprint.</em></h1><p class="lead">A group study for BU–SEN313 exploring the architectural design of a Student Campus App.</p></div><div class="people">${names.map(n=>`<article class="person"><span class="avatar" aria-hidden="true">${n.split(' ').slice(0,2).map(x=>x[0]).join('')}</span><div><h3>${n}</h3><p>Project creator</p></div></article>`).join('')}</div><div class="answers">${answer('The assignment','Group assignment 1: Architectural Design of a Mobile Application. Part 1 investigates MVC, MVP, MVVM, Redux / Flux, and BLoC. Part 2 examines five changes to the proposed architecture.')}${answer('Scope & approach','This website presents our simplified designs and architectural reasoning. It is an academic design submission, not an implemented campus service. Diagrams use a shared registration journey; the recommendation and scenario solutions are our proposed design judgments.')}</div><section class="references"><div class="eyebrow">Further reading</div><h2>References & foundations.</h2><p>The supplied assignment screenshots define the brief. These primary references support the pattern definitions; campus-specific designs and tradeoffs are developed for this assignment.</p><ol><li><a href="https://learn.microsoft.com/en-us/dotnet/architecture/maui/mvvm" target="_blank" rel="noreferrer">Microsoft — Model–View–ViewModel</a>. Separation of Views, ViewModels, Models, commands, and binding.</li><li><a href="https://redux.js.org/tutorials/fundamentals/part-2-concepts-data-flow" target="_blank" rel="noreferrer">Redux — Concepts and Data Flow</a>. Actions, reducers, store, and one-way updates.</li><li><a href="https://bloclibrary.dev/architecture/" target="_blank" rel="noreferrer">Bloc — Architecture</a>. Presentation, business logic, and data boundaries.</li><li><a href="https://martinfowler.com/eaaDev/uiArchs.html" target="_blank" rel="noreferrer">Martin Fowler — GUI Architectures</a>. MVC and MVP variants and their responsibilities.</li></ol></section></div>`}
function render(){let route=location.hash.slice(1)||'overview';const pages={overview,architectures:architecturePage,recommendation,scenarios:scenarioPage,about};if(!pages[route])route='overview';document.querySelector('main').innerHTML=pages[route]();document.querySelectorAll('nav a').forEach(a=>{let active=a.hash==='#'+(route==='recommendation'?'architectures':route);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=`${({overview:'Overview',architectures:'Architectures',recommendation:'Our recommendation',scenarios:'What if?',about:'About'})[route]} — Campus`;window.scrollTo(0,0);document.querySelectorAll('[data-architecture]').forEach(b=>{b.addEventListener('click',()=>selectArchitecture(+b.dataset.architecture));b.addEventListener('keydown',e=>{let i=+b.dataset.architecture;if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let next=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:4))%5;selectArchitecture(next);document.querySelector(`#tab-${next}`).focus()}})})}
function selectArchitecture(i){document.querySelectorAll('[data-architecture]').forEach((b,j)=>{b.setAttribute('aria-selected',i===j);b.tabIndex=i===j?0:-1});let panel=document.querySelector('#architecture-detail');panel.setAttribute('aria-labelledby',`tab-${i}`);panel.innerHTML=architectureDetail(i)}
window.addEventListener('hashchange',render);render();
